"""Historique des quantités des lignes de commande client : quantité commandée au départ,
quantité juste avant la livraison, quantité livrée, et produits retirés après la commande.

Reprise des commandes existantes :
- quantité commandée = quantité actuelle, sauf si les modifications tracées dans
  `notes_preparation` (« Café 10→8 », « +Lait x5 », « -Jus ») donnent la quantité d'origine ;
- commandes livrées : quantité livrée = quantité actuelle (la quantité avant livraison des
  anciennes livraisons n'a jamais été enregistrée : elle reste vide) ;
- produit retiré dont la quantité d'origine est connue par la trace : ajouté aux produits retirés.
"""
import re
from decimal import Decimal, InvalidOperation

from django.db import migrations, models

TRACE = re.compile(r'^\[[^\]]*\] Modifiée par .*? : (.*)$')
CHANGEMENT = re.compile(r'^(.+) (\d+(?:\.\d+)?)→(\d+(?:\.\d+)?)$')
AJOUT = re.compile(r'^\+(.+) x(\d+(?:\.\d+)?)$')
RETRAIT = re.compile(r'^-(.+)$')


def _dec(v):
    try:
        return Decimal(v)
    except (InvalidOperation, TypeError):
        return None


def premiers_evenements(notes):
    """{désignation: ('change', avant) | ('ajout', None) | ('retrait', None)} : premier événement
    connu de chaque produit dans les traces de modification."""
    evenements = {}
    for ligne in (notes or '').splitlines():
        m = TRACE.match(ligne.strip())
        if not m:
            continue
        for element in m.group(1).split(', '):
            element = element.strip()
            if element == 'notes modifiées':
                continue
            c = CHANGEMENT.match(element)
            if c:
                evenements.setdefault(c.group(1), ('change', _dec(c.group(2))))
                continue
            a = AJOUT.match(element)
            if a:
                evenements.setdefault(a.group(1), ('ajout', None))
                continue
            r = RETRAIT.match(element)
            if r:
                evenements.setdefault(r.group(1), ('retrait', None))
    return evenements


def reprendre(apps, schema_editor):
    CommandeClient = apps.get_model('API', 'CommandeClient')
    LigneCommandeClient = apps.get_model('API', 'LigneCommandeClient')
    Produit = apps.get_model('API', 'Produit')

    LigneCommandeClient.objects.filter(quantite_commandee__isnull=True).update(quantite_commandee=models.F('quantite'))
    LigneCommandeClient.objects.filter(commande__statut='delivered', quantite_livree__isnull=True).update(
        quantite_livree=models.F('quantite'))

    for commande in CommandeClient.objects.exclude(notes_preparation__isnull=True).exclude(notes_preparation=''):
        evenements = premiers_evenements(commande.notes_preparation)
        if not evenements:
            continue
        lignes = list(LigneCommandeClient.objects.filter(commande=commande).select_related('produit'))
        presents = set()
        for ligne in lignes:
            nom = ligne.produit.designation
            presents.add(nom)
            ev = evenements.get(nom)
            if ev is None:
                continue
            commandee = ev[1] if ev[0] == 'change' else Decimal('0') if ev[0] == 'ajout' else None
            if commandee is not None and commandee != ligne.quantite_commandee:
                LigneCommandeClient.objects.filter(pk=ligne.pk).update(quantite_commandee=commandee)
        retirees = list(commande.lignes_retirees or [])
        for nom, ev in evenements.items():
            # Produit absent aujourd'hui, dont la quantité d'origine est connue (« Jus 5→3 » puis « -Jus »)
            if nom in presents or ev[0] != 'change' or not ev[1]:
                continue
            produit = Produit.objects.filter(designation=nom).order_by('id').first()
            if produit is None or any(str(r.get('produit')) == str(produit.id) for r in retirees):
                continue
            retirees.append({'produit': produit.id, 'designation': nom, 'reference': produit.reference,
                             'quantite_commandee': str(ev[1])})
        if retirees != list(commande.lignes_retirees or []):
            CommandeClient.objects.filter(pk=commande.pk).update(lignes_retirees=retirees)


